export const WIDTH=192,DEPTH=144;
export const districts=['Maple Commons','Sunflower Fields','Civic Center','Harbor Heights','Willow Gardens','Copper Works','University Hill','East Village'];
export const typeNames={home:'Residence',market:'Food market',farm:'Community farm',park:'Neighborhood park',clinic:'Health clinic',library:'Learning center',work:'Workshop',shelter:'Storm shelter',empty:'Open land',forest:'Woodland',pond:'Rain garden'};
export const typeColors={home:'#e5aa87',market:'#e79b62',farm:'#a1b965',park:'#66b891',clinic:'#eb8796',library:'#9f92d3',work:'#82a9c4',shelter:'#87b4ae',empty:'#9fc875',forest:'#549a72',pond:'#78c7d4'};
export const clamp=(v,a=0,b=100)=>Math.max(a,Math.min(b,v));
export function makeCity(){const parcels=[];const types=['home','market','home','work','park','library','farm','home','clinic','home','shelter','empty'];for(let col=0;col<8;col++)for(let row=0;row<6;row++){const id=col*6+row,type=types[(id+Math.floor(col/2)*3)%types.length];parcels.push({id,x:-70+col*20,z:-50+row*20,type,original:type,district:col,name:`${districts[col]} ${typeNames[type]} ${id+1}`,quality:.75+(id%5)*.05})}return {parcels,closed:[],hazards:[],revision:1,history:[]}}
export function nearestParcel(world,x,z){return world.parcels.reduce((a,p)=>Math.hypot(p.x-x,p.z-z)<Math.hypot(a.x-x,a.z-z)?p:a)}
export const road=(v,limit)=>clamp(Math.round(v/20)*20,-limit,limit);
const key=(x,z)=>`${x},${z}`;
export function route(world,from,to){const sx=road(from.x,80),sz=road(from.z,60),ex=road(to.x,80),ez=road(to.z,60);const start=key(sx,sz),end=key(ex,ez),closed=new Set(world.closed),queue=[[sx,sz]],prev=new Map([[start,null]]);for(let i=0;i<queue.length;i++){const [x,z]=queue[i];if(key(x,z)===end)break;for(const [dx,dz]of [[20,0],[-20,0],[0,20],[0,-20]]){const nx=x+dx,nz=z+dz,k=key(nx,nz);if(nx<-80||nx>80||nz<-60||nz>60||prev.has(k)||(closed.has(k)&&k!==start))continue;prev.set(k,key(x,z));queue.push([nx,nz])}}if(!prev.has(end))return null;let path=[],k=end;while(k){const [x,z]=k.split(',').map(Number);path.unshift({x,z});k=prev.get(k)}const result=[{x:from.x,z:sz},...path,{x:to.x,z:ez},{x:to.x,z:to.z}];return result.filter((p,i)=>!i||Math.hypot(p.x-result[i-1].x,p.z-result[i-1].z)>.05)}
export function entrance(p,c){const slot=c.id%5;return {x:p.x-4+slot*2,z:p.z+1.4+(Math.floor(c.id/5)%2)*2.2}}
export function dangerAt(sim,x,z){return clamp(sim.world.hazards.reduce((s,h)=>s+Math.max(0,1-Math.hypot(x-h.x,z-h.z)/h.radius),0)+(sim.weather==='Storm'?.45:0),0,1)}
